def solve(path):
    """Simplify an absolute Unix path.
    Resolve '.' and '..', collapse multiple slashes, and remove any trailing slash.
    The root should be returned as '/'.
    """
    # Trim whitespace that might be present accidentally.
    path = path.strip()
    stack = []
    for part in path.split('/'):
        if not part or part == '.':
            # Skip empty components (caused by //) and current directory markers.
            continue
        if part == '..':
            # Go up one directory if possible.
            if stack:
                stack.pop()
        else:
            # Normal directory name.
            stack.append(part)
    # Reconstruct the simplified path.
    if not stack:
        return '/'
    return '/' + '/'.join(stack)

def solve(n, b):
    # Convert integer n to a string in base b (2 <= b <= 36).
    # Digits are 0-9 then a-z. Negative numbers get a leading '-'.
    # Assume b is in the valid range as per problem statement.
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

