def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Resolve '.' (current directory), '..' (parent directory), and collapse multiple slashes.
    The result is an absolute path without a trailing slash (unless it is the root '/').
    """
    parts = path.split('/')
    stack: list[str] = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components caused by '//' and current directory references.
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack is empty, we stay at root – do nothing.
        else:
            # Normal directory name (including names like '...').
            stack.append(part)
    # Reconstruct the simplified path.
    return '/' + '/'.join(stack) if stack else '/'

