def solve(strs):
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strs:
        key = tuple(sorted(s))
        groups[key].append(s)
    # sort each group alphabetically
    for lst in groups.values():
        lst.sort()
    # sort groups by first element, then by the whole group to ensure deterministic order when first elements tie
    return sorted(groups.values(), key=lambda g: (g[0] if g else '', g))

