def solve(line):
    """Parse a CSV line into a list of fields.
    Implements standard CSV quoting rules using the csv module for correctness.
    A trailing newline ("\n" or "\r\n") is ignored because it is not part of the data.
    If csv.reader raises an error (e.g., due to malformed quoting), a manual fallback parser
    is used that follows the same quoting semantics.
    """
    import csv
    # Remove a single trailing newline if present – other whitespace is significant.
    if line.endswith('\n') or line.endswith('\r'):
        line = line.rstrip('\r\n')
    if line == '':
        return ['']
    try:
        # csv.reader handles normal CSV quoting correctly.
        return next(csv.reader([line], delimiter=',', quotechar='"', doublequote=True))
    except Exception:
        # Manual fallback parser for edge‑cases where csv module fails.
        fields = []
        cur = []
        i = 0
        n = len(line)
        in_quotes = False
        while i < n:
            ch = line[i]
            if in_quotes:
                if ch == '"':
                    # Escaped quote?
                    if i + 1 < n and line[i + 1] == '"':
                        cur.append('"')
                        i += 1
                    else:
                        in_quotes = False
                else:
                    cur.append(ch)
            else:
                if ch == ',':
                    fields.append(''.join(cur))
                    cur = []
                elif ch == '"':
                    if not cur:  # start of quoted field
                        in_quotes = True
                    else:
                        # Quote inside unquoted field – treat as literal.
                        cur.append('"')
                else:
                    cur.append(ch)
            i += 1
        fields.append(''.join(cur))
