    if len(weights) != len(values):
        raise ValueError("weights and values must have same length")
    # Sum values of zero-weight items (they don't affect capacity)
    extra = 0
    filtered = []  # list of (weight, value) for weight > 0
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                extra += v
        elif w > 0:
            filtered.append((w, v))
        # ignore negative weights (invalid) - they are not expected
    # DP array for capacities 0..capacity
    dp = [0] * (capacity + 1)
    for w, v in filtered:
        if w > capacity:
            # cannot fit, skip
            continue
        # iterate backwards to ensure each item used at most once
        for cap in range(capacity, w - 1, -1):
            new_val = dp[cap - w] + v
            if new_val > dp[cap]:
                dp[cap] = new_val
    return dp[capacity] + extra

