{"task_id": "T30", "code": "def solve(path: str) -> str:
    """Simplify a Unix path.
    Handles absolute and relative paths, resolves '.' and '..',
    collapses duplicate slashes, and removes trailing slashes.
    For absolute input (starting with '/'), the result is absolute.
    For relative input, the result is relative (no leading slash).
    """
    # Strip whitespace that might surround the path.
    path = path.strip()
    is_abs = path.startswith('/')
    stack: list[str] = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # For relative paths, preserve leading '..'
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        # Relative path: if empty, return '.'
        return '/'.join(stack) if stack else '.'
