    """0/1 knapsack: maximum total value for any weight up to capacity.
    Uses DP over weight.
    """
    if capacity <= 0:
        return 0
    n = len(weights)
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w < 0:
            continue
        for cur in range(capacity, w - 1, -1):
            new_val = dp[cur - w] + v
            if new_val > dp[cur]:
                dp[cur] = new_val
    return max(dp)
