    Args:
        path (str): The input path.
    Returns:
        str: Simplified canonical path.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

