    Implements standard CSV quoting rules:
    * Fields may be wrapped in double quotes. Inside quoted fields commas are literal
      and a doubled double quote (""") represents a single quote.
    * An empty input line returns [''].
    * Trailing newline characters ("\n" or "\r\n") are ignored.
    """
    # Strip trailing newline characters.
    if line.endswith('\n') or line.endswith('\r'):
        line = line.rstrip('\r\n')
    if line == '':
        return ['']
    fields = []
    cur = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped double quote.
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quotes = False
                # Do not append the quote itself.
            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                # Start of a quoted field only if at the start of the field.
                if not cur:
                    in_quotes = True
                else:
                    # Quote in middle of unquoted field is treated as literal.
                    cur.append('"')
            else:
                cur.append(ch)
        i += 1
    # Append the final field.
    fields.append(''.join(cur))
    return fields

