def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than *n*.
    Implements the Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    # is_prime[i] == True means i is considered prime initially
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if is_prime[p]:
            # start marking from p*p to avoid redundant work
            start = p * p
            for multiple in range(start, n, p):
                is_prime[multiple] = False
    return sum(is_prime)

